import { sql } from "drizzle-orm";
import { boolean, doublePrecision, index, integer, jsonb, pgEnum, pgTable, text, timestamp, uniqueIndex } from "drizzle-orm/pg-core";

const timestamps = { createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(), updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow() };
export const businessState = pgEnum("business_state", ["TRIAL", "ACTIVE", "PAUSED", "EXPIRED", "CANCELLED"]);
export const trialExpiryBehavior = pgEnum("trial_expiry_behavior", ["PAUSE_AUTOMATION", "CONTINUE_AUTOMATION"]);
export const accountState = pgEnum("account_state", ["ACTIVE", "DISABLED"]);
export const versionState = pgEnum("agent_version_state", ["DRAFT", "TEST", "PUBLISHED", "ARCHIVED"]);
export const runState = pgEnum("agent_run_state", ["RUNNING", "COMPLETED", "FAILED", "CANCELLED"]);
