export const identityDecision = pgEnum("identity_decision", ["POSSIBLE_MATCH", "CONFIRMED_MATCH", "SEPARATE_IDENTITIES"]);
export const actionState = pgEnum("action_state", ["PENDING", "APPLIED", "DEFERRED", "FAILED"]);
export const onboardingState = pgEnum("onboarding_state", ["CREATED", "CLIENT_INVITED", "BUSINESS_INFO_READY", "KNOWLEDGE_PENDING", "AGENT_CONFIGURED", "AGENT_TESTED", "CHANNEL_PENDING", "PUBLISHED", "LIVE"]);
export const invitationScope = pgEnum("invitation_scope", ["AGENCY", "BUSINESS"]);
export const handoffPriority = pgEnum("handoff_priority", ["LOW", "NORMAL", "HIGH", "URGENT"]);
export const notificationDeliveryPreference = pgEnum("notification_delivery_preference", ["ENABLED", "DENIED", "UNAVAILABLE", "DISABLED"]);

